-- PR5.58: single SELECT only. Every passed value must be true; this does not publish anything.
WITH expected AS (SELECT value c FROM jsonb_array_elements($verify$[{"product":"medito","kind":"attribute","slug":"pricing-model","value":"Free public app and meditation content, supported by donations; no paid perpetual license is implied.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-m1-2026-10-15","meditation-m2-2026-10-15","meditation-m3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"medito","kind":"attribute","slug":"trade-off-summary","value":"A course-based meditation alternative rather than the complete Calm catalog. Core no-account access is vendor-documented but the owner tested signed in. App code licensing does not grant unrestricted reuse of original or partner audio.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-m1-2026-10-15","meditation-m2-2026-10-15","meditation-m3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"medito","kind":"attribute","slug":"no-subscription","value":true,"confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-m1-2026-10-15","meditation-m2-2026-10-15","meditation-m3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"medito","kind":"anchor","slug":"calm","scope":"personal-adult-guided-meditation-selection-playback","description":"For personal adult guided meditation, Medito lets you choose a session from its courses and play guided audio, as observed with Learning to sit. This substitutes for selecting and playing a Calm guided meditation; it does not establish equivalent catalog, sleep stories or health outcomes.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-m1-2026-10-15","meditation-m2-2026-10-15","meditation-m3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"smiling-mind","kind":"attribute","slug":"pricing-model","value":"Currently free individual access supported by the nonprofit; a registered account is required. This is not a perpetual-access guarantee.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-s1-2026-10-15","meditation-s2-2026-10-15","meditation-s3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"smiling-mind","kind":"attribute","slug":"trade-off-summary","value":"A broader mental-fitness app with adult, family and other sections; the comparison covers adult guided sessions only. Account registration is required. Download features are documented but offline playback was not tested.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-s1-2026-10-15","meditation-s2-2026-10-15","meditation-s3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"smiling-mind","kind":"attribute","slug":"no-subscription","value":true,"confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-s1-2026-10-15","meditation-s2-2026-10-15","meditation-s3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"smiling-mind","kind":"anchor","slug":"calm","scope":"personal-adult-guided-meditation-selection-playback","description":"For personal adult guided meditation, Smiling Mind lets you select an adult session and play guided audio, as observed with Exploring the Breath. This substitutes for the corresponding Calm selection/playback activity, without implying parity with Calm sleep stories, music or its entire catalog.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-s1-2026-10-15","meditation-s2-2026-10-15","meditation-s3-2026-10-15","meditation-owner-2026-10-15"]},{"product":"healthy-minds-program","kind":"attribute","slug":"pricing-model","value":"Free donor-funded public access with registration; donations are optional. Separate paid courses, workplace or research agreements are outside this edition.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-h1-2026-10-15","meditation-h2-2026-10-15","meditation-h3-2026-10-15","meditation-h4-2026-10-15","meditation-h5-2026-10-15","meditation-h6-2026-10-15","meditation-h7-2026-10-15","meditation-owner-2026-10-15"]},{"product":"healthy-minds-program","kind":"attribute","slug":"trade-off-summary","value":"A structured Awareness, Connection, Insight and Purpose program rather than the complete Calm catalog. Registration is required. Older offline instructions and conflicting documented iOS requirements remain limitations; the Android sample does not resolve them.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-h1-2026-10-15","meditation-h2-2026-10-15","meditation-h3-2026-10-15","meditation-h4-2026-10-15","meditation-h5-2026-10-15","meditation-h6-2026-10-15","meditation-h7-2026-10-15","meditation-owner-2026-10-15"]},{"product":"healthy-minds-program","kind":"attribute","slug":"no-subscription","value":true,"confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-h1-2026-10-15","meditation-h2-2026-10-15","meditation-h3-2026-10-15","meditation-h4-2026-10-15","meditation-h5-2026-10-15","meditation-h6-2026-10-15","meditation-h7-2026-10-15","meditation-owner-2026-10-15"]},{"product":"healthy-minds-program","kind":"anchor","slug":"calm","scope":"personal-adult-guided-meditation-selection-playback","description":"For personal adult guided meditation, the Healthy Minds public program lets you choose and play a guided practice, as observed with Intro To Sitting Meditation. This substitutes for Calm guided-session selection and playback within a structured learning program, not for every Calm content category.","confidence":0.85,"date":"2026-10-15T00:00:00.000Z","sources":["meditation-h1-2026-10-15","meditation-h2-2026-10-15","meditation-h3-2026-10-15","meditation-h4-2026-10-15","meditation-h5-2026-10-15","meditation-h6-2026-10-15","meditation-h7-2026-10-15","meditation-owner-2026-10-15"]}]$verify$::jsonb))
SELECT 'three_original_draft_products' check_name,(SELECT count(*)=3 AND bool_and(status='draft') FROM software_discovery.products WHERE slug IN ('medito','smiling-mind','healthy-minds-program')) passed
UNION ALL SELECT 'nine_exact_reviewed_attributes',(SELECT count(*)=9 AND bool_and((a.verification_status='verified' AND a.confidence=(c->>'confidence')::numeric AND a.last_verified_at=(c->>'date')::timestamptz AND CASE WHEN jsonb_typeof(c->'value')='boolean' THEN to_jsonb(a.value_boolean)=c->'value' AND a.value_text IS NULL ELSE to_jsonb(a.value_text)=c->'value' AND a.value_boolean IS NULL END AND a.value_number IS NULL AND a.value_enum IS NULL) IS TRUE) FROM expected JOIN software_discovery.products p ON p.slug=c->>'product' JOIN software_discovery.attributes t ON t.slug=c->>'slug' JOIN software_discovery.product_attributes a ON a.product_id=p.id AND a.attribute_id=t.id WHERE c->>'kind'='attribute')
UNION ALL SELECT 'three_exact_scoped_anchors',(SELECT count(*)=3 AND bool_and((a.relationship_scope=c->>'scope' AND a.scope_description=c->>'description' AND a.verification_status='verified' AND a.confidence=(c->>'confidence')::numeric AND a.last_verified_at=(c->>'date')::timestamptz) IS TRUE) FROM expected JOIN software_discovery.products p ON p.slug=c->>'product' JOIN software_discovery.anchors t ON t.slug=c->>'slug' JOIN software_discovery.product_anchors a ON a.product_id=p.id AND a.anchor_id=t.id AND a.relationship_type='alternative' WHERE c->>'kind'='anchor')
UNION ALL SELECT 'reviewed_attribute_evidence_linked',NOT EXISTS(SELECT 1 FROM expected WHERE c->>'kind'='attribute' AND (SELECT count(DISTINCT src.seed_key) FROM software_discovery.products p JOIN software_discovery.attributes t ON t.slug=c->>'slug' JOIN software_discovery.product_attribute_evidence l ON l.product_id=p.id AND l.attribute_id=t.id JOIN software_discovery.claim_evidence e ON e.id=l.claim_evidence_id JOIN software_discovery.evidence_sources src ON src.id=e.evidence_source_id WHERE p.slug=c->>'product' AND (c->'sources') ? src.seed_key)<>jsonb_array_length(c->'sources'))
UNION ALL SELECT 'reviewed_anchor_evidence_linked',NOT EXISTS(SELECT 1 FROM expected WHERE c->>'kind'='anchor' AND (SELECT count(DISTINCT src.seed_key) FROM software_discovery.products p JOIN software_discovery.anchors t ON t.slug=c->>'slug' JOIN software_discovery.product_anchor_evidence l ON l.product_id=p.id AND l.anchor_id=t.id AND l.relationship_type='alternative' JOIN software_discovery.claim_evidence e ON e.id=l.claim_evidence_id JOIN software_discovery.evidence_sources src ON src.id=e.evidence_source_id WHERE p.slug=c->>'product' AND (c->'sources') ? src.seed_key)<>jsonb_array_length(c->'sources'))
