d under an open-source license according to current official materials."},{"id":"83353c3f-3cd2-4505-8311-f722e720867c","name":"Pricing Model","slug":"pricing-model","category":"pricing","created_at":"2026-10-06T03:22:38.833862+00:00","updated_at":"2026-10-06T03:22:38.833862+00:00","value_type":"text","description":"Source-backed pricing model and relevant edition scope; excludes transient numeric prices."},{"id":"2e5f8446-3bb6-4e92-990e-d6c253d2417c","name":"Supported Platforms","slug":"supported-platforms","category":"platform","created_at":"2026-10-06T03:22:38.833862+00:00","updated_at":"2026-10-06T03:22:38.833862+00:00","value_type":"text","description":"Source-listed platforms and edition scope; an omitted platform is not a verified negative."},{"id":"18dee1eb-8a8a-45fa-b463-8487065642d9","name":"Trade-Off Summary","slug":"trade-off-summary","category":"workflow","created_at":"2026-10-06T03:22:38.833862+00:00","updated_at":"2026-10-06T03:22:38.833862+00:00","value_type":"text","description":"Evidence-backed restrictions or explicitly provisional editorial interpretation, with confidence status."},{"id":"2d9835d9-4aa0-4fb3-93fa-2c98d4f890c4","name":"Works Offline","slug":"works-offline","category":"offline","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","value_type":"boolean","description":"Core work remains available without an internet connection."}]$verify$::jsonb) x WHERE NOT EXISTS(SELECT 1 FROM software_discovery.attributes t WHERE to_jsonb(t)-'created_at'-'updated_at'=to_jsonb(jsonb_populate_record(NULL::software_discovery.attributes,x))-'created_at'-'updated_at'))
